    { const char * tb_v1545 = "    if (l->data == 0) tb_crash(line, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1545; }
    { const char * tb_v1546 = "    memset(l->data, 0, bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v1546; }
    { const char * tb_v1547 = "    l->len = 0; l->cap = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v1547; }
    { const char * tb_v1548 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1548; }
    { const char * tb_v1549 = "static void tb_dclear(tb_dict *d, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1549; }
    { const char * tb_v1550 = "    tb_lclear(d->keys, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v1550; }
