    { const char * tb_v1699 = "static void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1699; }
    { const char * tb_v1700 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v1700; }
